import {createState,portfolio,simulatePlan,executePlan,validateState,allocationCeiling,csvExport,recordCashFlow,applySplit,updatePlan,reviewPlanState,planReviewFresh,makeRemainingPlan} from './model.js';
import {createRemoteStore} from './client-store.js';
import {parseQuoteCSV,quoteTemplate,applyQuoteRows,decisionMetrics,dailyReport,tradeCSV} from './data-tools.js';

const $=(s,r=document)=>r.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=v=>JSON.parse(JSON.stringify(v));
const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const labels={core:'核心成长',flex:'弹性成长',defense:'防守资产',stronger:'增强',stable:'稳定',weaker:'减弱',unknown:'待判断',attractive:'有吸引力',fair:'大致合理',expensive:'偏贵',pending:'待核实',verified:'已核实',refuted:'已证伪',positive:'积极',neutral:'中性',negative:'负面',draft:'待审查',reviewed:'已审查',executed:'已记账',cancelled:'已取消',buy:'买入',sell:'卖出',thesis:'逻辑变化',valuation:'估值变化',risk:'风险再平衡',opportunity:'新增机会',growth:'成长资产',cash:'机会现金'};
const navs=[['dashboard','◫','今日工作台'],['holdings','▤','持仓与观察'],['research','◎','事件与证据'],['risk','◉','风险与杠铃'],['plans','⇄','交易计划'],['review','↺','交易复盘'],['settings','⚙','账户与数据']];
const mode='hone';
let lifecycle=0,mainInitial=new Map(),downloadPanel=null,downloadUrl=null,downloadTimer;
let state=null,view=location.hash.slice(1)||'dashboard',search='',planFilter='all',toastTimer;
let storageError='',storeApi,uiSaving=false,loading=true,authMessage='正在验证 Hone 登录并加载账户…',checkingSession=false,holdingFilter='all',holdingSort='weight',eventFilter='open',eventSearch='',reportFrom='',reportTo='',modalInitial='',quotePreview=null;
async function commit(next,label='保存资料'){return persistOperation(()=>storeApi.commit(next,label));}
async function persistOperation(operation){if(uiSaving)throw Error('正在保存上一项修改，请等待完成。');if(!state)throw Error('请先成功加载账户。');setSaving(true);const generation=lifecycle;try{const saved=await operation();if(generation!==lifecycle||!state)throw Error('登录状态已变化，旧保存结果已丢弃。');state=saved;storageError='';$('#save-status').textContent='● 服务器已保存';return state;}catch(error){if(generation===lifecycle)presentStoreError(error);throw error;}finally{if(generation===lifecycle)setSaving(false);}}
function setSaving(value){uiSaving=value;document.querySelectorAll('button,input,select,textarea').forEach(el=>{if(value&&!el.disabled){el.disabled=true;el.dataset.savingDisabled='true';}else if(!value&&el.dataset.savingDisabled){el.disabled=false;delete el.dataset.savingDisabled;}});if(value)$('#save-status').textContent='正在保存到服务器…';syncHostStatus();}
function clearSensitive(reason,cause='auth'){lifecycle++;clearDownload();loading=cause==='reload';if(cause==='auth'&&parent!==window)parent.postMessage({type:'hone:trade-auth-invalidated'},location.origin);state=null;uiSaving=false;checkingSession=false;mainInitial.clear();quotePreview=null;search='';eventSearch='';reportFrom='';reportTo='';storageError='';authMessage=reason;modalInitial='';if($('#modal').open)$('#modal').close();$('#modal-content').replaceChildren();$('#import-file').value='';clearTimeout(toastTimer);$('#toast').hidden=true;$('#toast').textContent='';$('#nav').replaceChildren();renderLocked();syncHostStatus();}
function renderLocked(){document.querySelectorAll('[data-action="export"],[data-action="command-palette"]').forEach(el=>el.hidden=true);$('#save-status').textContent=loading?'正在加载…':'未加载账户';$('#crumb').textContent='Hone 个人交易账户';$('#account-label').textContent='Hone 身份验证';$('#main').innerHTML=`<section class="card"><div class="card-body" style="padding-top:28px"><h1>${loading?'正在加载交易账户':'账户尚未加载'}</h1><p role="status">${esc(authMessage)}</p><p class="muted">数据由 Hone 当前登录身份决定。连接失败时不会展示示例账户，也不会创建替代数据。</p><div class="actions">${loading?'':btn('重新验证并加载','retry-load','primary')}${btn('返回 Hone','host-close','secondary')}</div></div></section>`;}
function presentStoreError(error){if(!state)return;storageError=error.message;$('#save-status').textContent='未保存 · 请核对';const el=$('#form-error');if(el){el.textContent=error.message;if(storeApi.getPendingState()){const button=document.createElement('button');button.type='button';button.className='btn secondary small';button.dataset.action='download-pending';button.textContent='下载本次待保存副本';el.append(document.createElement('br'),button);}}else render();syncHostStatus();}
async function bootstrap(){loading=true;clearSensitive('正在验证 Hone 登录并加载账户…','reload');const operation=storeApi.load(),generation=lifecycle;try{const loaded=await operation;if(generation!==lifecycle)return;state=loaded;loading=false;authMessage='';render();if(view==='risk')updateScenario();}catch(error){if(generation!==lifecycle)return;loading=false;authMessage=error.message;renderLocked();}}
async function refreshSession(){if(!state||uiSaving||checkingSession)return;checkingSession=true;const generation=lifecycle;try{await storeApi.checkSession();}catch(error){if(generation===lifecycle&&state){presentStoreError(error);if(!$('#modal').open)render();}}finally{if(generation===lifecycle)checkingSession=false;}}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
const fmt=(n,d=0)=>Number.isFinite(Number(n))?Number(n).toLocaleString('zh-CN',{maximumFractionDigits:d,minimumFractionDigits:d}):'—';
const money=n=>`${state.settings.currency} ${fmt(n,2)}`;
const pct=n=>`${fmt(n,1)}%`;
const tag=(text,color='neutral')=>`<span class="pill ${color}">${esc(text)}</span>`;
const stateTag=(value)=>tag(labels[value]||value,['stronger','attractive','verified','executed','positive'].includes(value)?'green':['weaker','negative','refuted'].includes(value)?'red':['pending','expensive','draft','unknown'].includes(value)?'amber':'neutral');
const btn=(text,action,klass='secondary',attrs='')=>`<button type="button" class="btn ${klass}" data-action="${action}" ${attrs}>${text}</button>`;
const empty=(title,desc,button='')=>`<div class="empty-state"><div class="empty-icon">◇</div><h3>${title}</h3><p>${desc}</p>${button}</div>`;
function heading(eyebrow,title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${desc}</p></div><div class="actions">${actions}</div></div>`;}
function card(title,body,action='',extra=''){return `<section class="card ${extra}"><div class="card-header"><h2>${title}</h2>${action}</div><div class="card-body">${body}</div></section>`;}
function sourceLink(url){try{const u=new URL(url);if(!['https:','http:'].includes(u.protocol))return esc(url);return `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">查看来源 ↗</a>`;}catch{return esc(url||'未填写来源');}}
function navigate(to){view=to;search='';location.hash=to;render();window.scrollTo(0,0);}
function render(){if(!state){renderLocked();return;}document.querySelectorAll('[data-action="export"],[data-action="command-palette"]').forEach(el=>el.hidden=false);const known=navs.map(n=>n[0]).concat('method');if(!known.includes(view))view='dashboard';$('#nav').innerHTML=navs.map(([id,icon,title])=>`<button class="nav-item ${view===id?'active':''}" data-action="navigate" data-view="${id}" ${view===id?'aria-current="page"':''}><span class="nav-icon">${icon}</span><span class="nav-label">${title}</span>${id==='plans'&&state.plans.filter(p=>p.status==='draft').length?`<span class="nav-count">${state.plans.filter(p=>p.status==='draft').length}</span>`:''}</button>`).join('');$('#crumb').textContent=navs.find(n=>n[0]===view)?.[2]||'方法与规则';$('#account-label').textContent='Hone 个人账户';$('#save-status').textContent=storageError?'未保存 / 版本待核对':`● 服务器版本 ${storeApi.getStatus().revision}`;const banner=storageError?`<div class="mode-banner"><span>${esc(storageError)}</span>${storeApi.getPendingState()?btn('下载待保存副本','download-pending','secondary small'):''}${btn('重新加载服务器账户','retry-load','secondary small')}</div>`:'';$('#main').innerHTML=banner+({dashboard:dashboard,holdings:holdings,research:research,risk:risk,plans:plans,review:review,settings:settings,method:method}[view])();captureMainForms();syncHostStatus();}
function allocation(p){return `<div class="allocation-bar" role="img" aria-label="成长 ${pct(p.growthPct)}，防守 ${pct(p.defensePct)}，现金 ${pct(p.cashPct)}"><span class="core" style="width:${p.growthPct}%"></span><span class="defense" style="width:${p.defensePct}%"></span><span class="cash" style="width:${p.cashPct}%"></span></div><div class="allocation-legend"><div class="legend-item"><i class="dot core"></i>成长 <strong>${pct(p.growthPct)}</strong></div><div class="legend-item"><i class="dot defense"></i>防守 <strong>${pct(p.defensePct)}</strong></div><div class="legend-item"><i class="dot cash"></i>现金 <strong>${pct(p.cashPct)}</strong></div></div>`;}
function alerts(p,limit=99){return p.alerts.length?`<div class="alert-list">${p.alerts.slice(0,limit).map(a=>`<div class="alert-item ${a.level}"><span class="alert-dot ${a.level}"></span><div class="alert-content"><strong>${esc(a.title)}</strong><p>${esc(a.detail)}</p></div></div>`).join('')}</div>`:`<div class="note-box">当前输入未触发已设置的阈值。仍需检查数据完整性与重大事件。</div>`;}
function dashboard(){const p=portfolio(state),pending=state.events.filter(e=>!e.reviewed).length,planN=state.plans.filter(x=>['draft','reviewed'].includes(x.status)).length,d=today();const checks=state.checks[d]||{};return heading('DAILY WORKSPACE',`今天，先检查逻辑与风险`,'从企业价值出发，让每一次操作都有可复核的依据。',btn('导出今日报告','daily-report','secondary')+btn('＋ 新建交易计划','new-plan','primary'))+onboarding()+`<div class="stats-grid"><div class="stat-card"><div class="stat-label">可投资资产 <span>${esc(state.settings.currency)}</span></div><div class="stat-value">${p.total?fmt(p.total):'待设置'}</div><div class="stat-note">生活保障现金单独管理</div></div><div class="stat-card"><div class="stat-label">机会现金 / 资产占比</div><div class="stat-value">${pct(p.cashPct)}</div><div class="stat-note">${money(p.cash)}</div></div><div class="stat-card"><div class="stat-label">情景压力损失</div><div class="stat-value ${p.stressPct>state.settings.budget?'negative':''}">${pct(p.stressPct)}</div><div class="stat-note">预算 ${pct(state.settings.budget)} · 假设演算</div></div><div class="stat-card"><div class="stat-label">待办 / 事件与计划</div><div class="stat-value">${pending+planN}<small> 项</small></div><div class="stat-note">${pending} 条事件 · ${planN} 笔计划</div></div></div><div class="dashboard-grid">${card('今日检查',`<div class="small muted">${esc(d)} · 北京时间 · 核查完成也可以选择不交易</div><div class="checklist">${[['quotes','确认持仓数量与价格日期','价格来自手工录入，请以券商账单核对'],['events','复核新事件与证伪条件','先区分事实、传闻和自己的推演'],['risk','查看风险预算与集中度','不同 AI 股票可能受到同一风险影响'],['decision','记录今天的决定','持有不动，也是一项有效决定']].map(([k,t,s])=>`<label class="check-row"><input type="checkbox" data-check="${k}" ${checks[k]?'checked':''}><span><strong>${t}</strong><small>${s}</small></span></label>`).join('')}</div>`,tag(`${Object.values(checks).filter(Boolean).length}/4`))}${card('组合杠铃',allocation(p)+`<div class="metric-row"><span>目标成长 / 防守 / 现金</span><strong>${state.settings.targetGrowth}% / ${state.settings.targetDefense}% / ${state.settings.targetCash}%</strong></div><div class="note-box">先看风险能否承受，再决定是否调整。示例目标和阈值均可修改。</div>`,btn('压力演算 ↗','navigate','ghost small','data-view="risk"'))}${card('需要你关注',alerts(p,4),btn('查看风险','navigate','ghost small','data-view="risk"'))}${card('最近的证据变化',state.events.length?eventList(state.events.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3),true):empty('还没有事件','记录财报、竞争变化或宏观事件。'),btn('记录事件 ＋','new-event','ghost small'))}</div>`;}
function holdingTable(rows){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>标的 / 资产类型</th><th>持仓市值 / 权重</th><th>数量 / 均价</th><th>参考价 / 日期</th><th>稀缺 / 差异化</th><th>估值判断</th><th>操作</th></tr></thead><tbody>${rows.map(h=>`<tr><td><div class="position-symbol">${esc(h.symbol)}</div><div class="company-name">${esc(h.name)} · ${labels[h.bucket]}</div><small class="muted">${esc(h.sector)} / ${esc(h.theme)}</small></td><td><strong>${money(h.value)}</strong><div class="small muted">${pct(h.weight)}</div><div class="small ${h.pnl<0?'negative':'positive'}">浮盈亏 ${money(h.pnl)}</div></td><td>${fmt(h.quantity,4)}<div class="small muted">${fmt(h.cost,2)}</div></td><td>${h.price>0?fmt(h.price,2):'待录入'}<div class="small muted">${esc(h.priceDate||'未标日期')}</div></td><td>${stateTag(h.scarcity)} ${stateTag(h.differentiation)}</td><td>${stateTag(h.valuation)}</td><td><div class="actions">${btn('编辑','edit-holding','ghost small',`data-id="${h.id}"`)}${btn('计划','new-plan','ghost small',`data-id="${h.id}"`)}</div></td></tr>`).join('')}</tbody></table></div>`;}
function holdings(){const p=portfolio(state);let rows=p.holdings.filter(h=>`${h.symbol} ${h.name} ${h.sector} ${h.theme}`.toLowerCase().includes(search.toLowerCase()));rows=rows.filter(h=>holdingFilter==='all'?!h.archived:holdingFilter==='held'?h.quantity>0:holdingFilter==='watch'?h.quantity===0&&!h.archived:holdingFilter==='stale'?h.priceStale:holdingFilter==='review'?h.reviewDue||h.scarcity==='weaker'||h.differentiation==='weaker':h.archived);rows.sort((a,b)=>holdingSort==='symbol'?a.symbol.localeCompare(b.symbol):holdingSort==='pnl'?a.pnl-b.pnl:holdingSort==='date'?(a.priceDate||'').localeCompare(b.priceDate||''):b.weight-a.weight);return heading('PORTFOLIO & THESIS','持仓与观察','按关注事项筛选，批量更新报价，再复核企业长期逻辑。',btn('批量更新报价','bulk-quotes','secondary')+btn('＋ 添加标的','new-holding','primary'))+`<div class="toolbar"><input class="search-input" id="holding-search" aria-label="搜索持仓" placeholder="搜索代码、名称或板块…" value="${esc(search)}"><select id="holding-filter" aria-label="筛选持仓">${[['all','全部未归档'],['held','实际持仓'],['watch','观察名单'],['stale','价格待更新'],['review','逻辑待复核'],['archived','已归档']].map(([v,t])=>`<option value="${v}" ${v===holdingFilter?'selected':''}>${t}</option>`).join('')}</select><select id="holding-sort" aria-label="排序持仓">${[['weight','按仓位从高到低'],['symbol','按代码'],['pnl','按浮盈亏从低到高'],['date','按报价日期从旧到新']].map(([v,t])=>`<option value="${v}" ${v===holdingSort?'selected':''}>${t}</option>`).join('')}</select>${btn('持仓 CSV','csv','secondary small')}</div>`+card(`${rows.length} 个标的 · ${esc(state.settings.currency)}`,rows.length?holdingTable(rows):empty('当前筛选下没有标的','可调整筛选条件，或添加持仓和观察标的。',btn('添加标的','new-holding','primary')))+`<div class="section-title"><h2>投资逻辑卡</h2><span class="muted small">财报或重大事件后复核</span></div><div class="grid-2">${rows.map(h=>`<section class="card thesis-card"><div class="card-header"><h2>${esc(h.symbol)} <small class="muted">${esc(h.name)}</small></h2>${btn('复核逻辑','edit-holding','ghost small',`data-id="${h.id}"`)}</div><div class="card-body"><p>${esc(h.thesis||'尚未填写投资逻辑')}</p><div class="note-box"><strong>证伪条件</strong><p>${esc(h.invalidation||'尚未设定')}</p></div><div class="metric-row"><span>价值区间（个人假设）</span><strong>${h.low>0&&h.base>0&&h.high>0?`${fmt(h.low)} / ${fmt(h.base)} / ${fmt(h.high)}`:'未设置'}</strong></div><div class="small muted">最近复核 ${esc(h.reviewDate||'未记录')} · 下次关注 ${esc(h.nextReview||'事件触发')}</div><div class="small">证据：${sourceLink(h.evidence)}</div><div class="actions" style="margin-top:14px">${btn('关联事件','holding-events','secondary small',`data-id="${h.id}"`)}${btn('拆股登记','split','ghost small',`data-id="${h.id}"`)}${h.quantity===0?btn(h.archived?'恢复观察':'归档观察','archive-holding','ghost small',`data-id="${h.id}"`):''}</div></div></section>`).join('')}</div>`;}
function eventList(items,compact=false){return `<div class="event-list">${items.map(e=>{const h=state.holdings.find(h=>h.symbol.toUpperCase()===e.symbol.toUpperCase());return `<article class="event-item"><div class="event-date">${esc(e.date)}${e.followUp?`<div class="small ${e.followUp<=today()&&!e.reviewed?'negative':''}">跟进 ${esc(e.followUp)}</div>`:''}</div><div class="event-content"><div class="actions">${tag(e.symbol||'宏观')} ${stateTag(e.verification)} ${!compact?stateTag(e.impact):''}</div><h3>${esc(e.title)}</h3><p>${esc(e.note||'尚未记录对基本面的影响')}</p>${!compact?`<div class="small muted">${esc(e.type)} · ${sourceLink(e.source)}</div><div class="actions" style="margin-top:12px">${btn('编辑与核实','edit-event','ghost small',`data-id="${e.id}"`)}${h?btn(`复核 ${esc(h.symbol)} 逻辑`,'edit-holding','secondary small',`data-id="${h.id}"`):''}${e.verification==='pending'?tag('核实后再完成复核','amber'):btn(e.reviewed?'已复核 · 重新打开':'标记复核完成','review-event','secondary small',`data-id="${e.id}"`)}</div>`:''}</div>${e.reviewed?tag('已复核','green'):''}</article>`;}).join('')}</div>`;}
function research(){let events=state.events.filter(e=>(eventFilter==='all'||eventFilter==='open'&&!e.reviewed||eventFilter==='pending'&&e.verification==='pending'||eventFilter==='negative'&&e.impact==='negative'&&!e.reviewed||eventFilter==='done'&&e.reviewed)&&`${e.symbol} ${e.title} ${e.note}`.toLowerCase().includes(eventSearch.toLowerCase()));return heading('EVIDENCE BEFORE ACTION','事件与证据','事实核实与投资判断分别记录；把相关事件带回企业逻辑卡。',btn('＋ 记录事件','new-event','primary'))+`<div class="toolbar"><input id="event-search" class="search-input" aria-label="搜索事件" value="${esc(eventSearch)}" placeholder="搜索标的或事件内容…"><select id="event-filter" aria-label="筛选事件">${[['open','待处理'],['all','全部事件'],['pending','待核实'],['negative','负面待复核'],['done','已完成']].map(([v,t])=>`<option value="${v}" ${v===eventFilter?'selected':''}>${t}</option>`).join('')}</select><span class="small muted">${events.length} 条记录</span></div><div class="note-box" style="margin-bottom:20px">消息待核实期间，保持问题开放。核实后再评估稀缺性、差异化和现金流；复核结论不会自动改变仓位。</div>`+card('事件时间线',events.length?eventList(events.slice().sort((a,b)=>b.date.localeCompare(a.date))):empty('当前没有匹配事件','可以切换“全部事件”，或记录新的证据。'));}
function risk(){const p=portfolio(state),s=state.settings,ceil=allocationCeiling(s.budget,s.growthShock,s.defenseShock);return heading('RISK & BARBELL','风险与动态杠铃','把现金留多少，转化为可解释的情景演算。参数是你的假设，不是市场预测。',btn('修改风险参数','edit-risk','primary'))+`<div class="stats-grid"><div class="stat-card"><div class="stat-label">压力损失金额</div><div class="stat-value">${fmt(p.stressLoss)}</div><div class="stat-note">${esc(s.currency)} · 全部资产同时受压</div></div><div class="stat-card"><div class="stat-label">压力损失率 / 预算</div><div class="stat-value ${p.stressPct>s.budget?'negative':''}">${pct(p.stressPct)}</div><div class="stat-note">预算 ${pct(s.budget)}</div></div><div class="stat-card"><div class="stat-label">当前成长资产占比</div><div class="stat-value">${pct(p.growthPct)}</div><div class="stat-note">核心成长 ＋ 弹性成长</div></div><div class="stat-card"><div class="stat-label">生活保障现金</div><div class="stat-value">${fmt(s.lifeCash)}</div><div class="stat-note">不计入可投资资产，不用于交易</div></div></div><div class="split-grid">${card('压力情景实验室',`<form id="risk-inline"><div class="range-row"><label for="growthShock">成长资产跌幅 <strong id="growthShock-label">${s.growthShock}%</strong></label><input id="growthShock" name="growthShock" type="range" min="0" max="100" value="${s.growthShock}"></div><div class="range-row"><label for="defenseShock">防守资产跌幅 <strong id="defenseShock-label">${s.defenseShock}%</strong></label><input id="defenseShock" name="defenseShock" type="range" min="0" max="100" value="${s.defenseShock}"></div><div class="range-row"><label for="cashShock">现金损失假设 <strong id="cashShock-label">${s.cashShock}%</strong></label><input id="cashShock" name="cashShock" type="range" min="0" max="100" value="${s.cashShock}"></div><div id="scenario-result" class="note-box"></div><button class="btn primary" type="submit" style="margin-top:16px">保存此情景</button></form><p class="small muted">损失 = 成长市值 × 成长跌幅 + 防守市值 × 防守跌幅 + 现金 × 现金损失率。未建模杠杆、衍生品、汇率和跳空等风险。</p>`)}${card('配置与偏离',allocation(p)+`<div class="stack">${[['growth','成长',s.targetGrowth],['defense','防守',s.targetDefense],['cash','现金',s.targetCash]].map(([k,l,t])=>`<div class="metric-row"><span>${l}目标 ${t}%</span><strong class="${Math.abs(p.drift[k])>s.buffer?'negative':''}">偏离 ${p.drift[k]>0?'+':''}${fmt(p.drift[k],1)} 个百分点</strong></div>`).join('')}</div><div class="note-box">缓冲带 ±${s.buffer} 个百分点。超出时进入评估，不自动生成买卖。<br>本月战术调整累计 ${fmt(p.monthlyTacticalChangePct||0,2)} 个百分点 / 提醒阈值 ${s.maxMonthly}。仅统计标记为风险再平衡的已记账成交，累计成长占比变化的绝对值，非净变化。${p.monthlyTacticalUnknownCount?'有旧记录缺少快照，统计不完整。':''}</div><div class="small muted" style="margin-top:12px">两类资产简化演算：其余资金全部配置防守资产时，成长上限 ${ceil===null?'无法由当前假设确定':pct(ceil)}。仅作数学约束，不是推荐配置。</div>`)}${card('集中度与风险提醒',alerts(p))}${card('市场水温 · 人工观察',`<div class="metric-row"><span>当前判断</span>${tag(({positive:'偏积极',neutral:'中性',negative:'偏谨慎',unknown:'待判断'})[s.market]||'待判断',s.market==='negative'?'amber':'neutral')}</div><p>${esc(s.marketNote||'记录利率、信用、AI 资本开支、重大政策与竞争事件，再说明它们如何影响现金流或风险。')}</p><div class="note-box">市场温度用于触发复核，不直接换算成交易信号。防守型股票仍有股票风险，请赋予合理压力跌幅。</div>`,btn('更新观察','edit-risk','ghost small'))}</div>`+riskComparison();}
function planCard(p){const h=state.holdings.find(h=>h.id===p.holdingId);const sim=['draft','reviewed'].includes(p.status)?simulatePlan(state,p):null;return `<section class="card plan-card"><div class="plan-header"><div class="actions">${tag(labels[p.side],p.side==='buy'?'green':'amber')}<h2>${esc(p.symbol)}</h2>${stateTag(p.status)}${p.status==='reviewed'&&!planReviewFresh(state,p)?tag('资料变化 · 重新审查','amber'):''}</div><span class="small muted">${esc(p.date)}</span></div><div class="plan-meta"><strong>${p.status==='executed'?'原计划：':''}${fmt(p.quantity,4)} 股 × ${fmt(p.price,2)}</strong><span>${money(p.quantity*p.price)} · ${labels[p.reason]}</span></div><p>${esc(p.rationale)}</p>${sim?`<div class="note-box ${sim.valid?'':'negative'}">${sim.valid?`交易后成长占比 ${pct(sim.after.growthPct)} · 现金 ${money(sim.after.cash)} · 压力损失 ${pct(sim.after.stressPct)}`:esc(sim.errors.join('；'))}</div>`:''}${p.cancelReason?`<div class="note-box">${esc(p.cancelReason)}</div>`:''}${p.execution?`<div class="note-box">实际 ${fmt(p.execution.quantity??p.quantity,4)} 股 × ${fmt(p.execution.price??p.price,2)} · 手续费 ${money(p.execution.fee??p.fee)}<br>成交已计入持仓与现金，${p.side==='sell'?`已实现盈亏 ${money(p.execution.realizedPnl??0)}`:'买入成本含手续费'}。</div>`:''}<div class="plan-footer"><span class="small muted">${Object.values(p.checklist||{}).filter(Boolean).length}/4 项审查</span><div class="actions">${(p.status==='draft'||p.status==='reviewed'&&!planReviewFresh(state,p))?btn('审查计划','review-plan','primary small',`data-id="${p.id}"`):''}${p.status==='reviewed'&&planReviewFresh(state,p)?btn('录入实际成交','execute-plan','primary small',`data-id="${p.id}"`):''}${['draft','reviewed'].includes(p.status)?btn('修改计划','edit-plan','ghost small',`data-id="${p.id}"`):''}${p.status==='executed'&&p.execution?.remainingQuantity>0&&!state.plans.some(x=>x.sourcePlanId===p.id)?btn('建立剩余数量计划','remaining-plan','secondary small',`data-id="${p.id}"`):''}${['draft','reviewed'].includes(p.status)?btn('取消','cancel-plan','ghost small',`data-id="${p.id}"`):''}</div></div></section>`;}
function plans(){const filtered=state.plans.filter(p=>planFilter==='all'||p.status===planFilter);return heading('PLAN → REVIEW → RECORD','交易计划','先写原因、检查交易后风险，再由你在券商端操作，最后录入实际成交。',btn('＋ 新建计划','new-plan','primary'))+`<div class="tabs" role="tablist">${[['all','全部'],['draft','待审查'],['reviewed','已审查'],['executed','已记账'],['cancelled','已取消']].map(([id,t])=>`<button class="tab ${planFilter===id?'active':''}" data-action="filter-plan" data-filter="${id}">${t}</button>`).join('')}</div><div class="grid-2">${filtered.length?filtered.slice().reverse().map(planCard).join(''):empty('目前没有这类计划','持有不动也可以记录在复盘中。',btn('新建交易计划','new-plan','primary'))}</div>`;}
function review(){const executions=decisionMetrics(state,{from:reportFrom,to:reportTo}).records;const journalRows=state.journal.filter(j=>(!reportFrom||j.date>=reportFrom)&&(!reportTo||j.date<=reportTo));const realized=executions.filter(p=>p.side==='sell').reduce((n,p)=>n+(p.execution?.realizedPnl||0),0);return heading('DECISION JOURNAL','交易复盘','分别检查判断质量、执行纪律和投资结果。没有交易的一天也值得记录。',btn('导出今日报告','daily-report','secondary')+btn('＋ 写复盘','new-journal','primary'))+metricsPanel()+`<div class="stats-grid"><div class="stat-card"><div class="stat-label">已记账成交</div><div class="stat-value">${executions.length}</div><div class="stat-note">仅统计所选期间的已登记成交</div></div><div class="stat-card"><div class="stat-label">已实现盈亏</div><div class="stat-value ${realized<0?'negative':'positive'}">${fmt(realized,2)}</div><div class="stat-note">含已录入费用 · 非完整账户收益</div></div><div class="stat-card"><div class="stat-label">期间复盘</div><div class="stat-value">${journalRows.length}</div><div class="stat-note">把经验转化为下一次的行动</div></div><div class="stat-card"><div class="stat-label">明确遵守纪律</div><div class="stat-value">${journalRows.filter(j=>j.discipline==='yes').length}</div><div class="stat-note">按复盘自评记录统计</div></div></div>`+card('决策日记',journalRows.length?`<div class="event-list">${journalRows.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(j=>`<article class="event-item"><div class="event-date">${esc(j.date)}</div><div class="event-content">${tag(j.discipline==='yes'?'遵守纪律':j.discipline==='no'?'存在偏离':'持有不动',j.discipline==='no'?'amber':'green')}<h3>${esc(j.lesson)}</h3><p>下次行动：${esc(j.next||'暂不调整')}</p>${btn('编辑','edit-journal','ghost small',`data-id="${j.id}"`)}</div></article>`).join('')}</div>`:empty('留下第一次判断','记录今天为什么交易，或为什么继续持有。',btn('写一条复盘','new-journal','primary')))+`<div class="section-title"><h2>成交记录</h2>${btn('导出成交 CSV','trades-csv','secondary small')}</div>`+(executions.length?`<div class="grid-2">${executions.slice().reverse().map(planCard).join('')}</div>`:empty('暂无成交记录','审查交易计划后，可录入券商实际成交。'))+ledgerTable();}
function settings(){const s=state.settings;return heading('ACCOUNT & DATA','账户与数据','此工具是独立的个人交易账本，不会自动读取或修改 Hone 的其他持仓；同一账户的金额须使用同一币种。')+`<div class="split-grid">${card('账户资金',`${btn('登记入金 / 出金 / 分红','cash-flow','secondary small')}<p class="small muted">日常资金变化请通过资金流水登记，下面仅用于初始基线或对账。</p><form id="account-form" class="form-grid">${field('currency','账户币种','select',s.currency,{options:[['USD','美元 USD'],['CNY','人民币 CNY'],['HKD','港元 HKD'],['EUR','欧元 EUR'],['GBP','英镑 GBP'],['JPY','日元 JPY']]})}${field('cash','账户内可用现金','number',s.cash,{min:0,step:'0.01'})}${field('lifeCash','生活保障现金（账户外）','number',s.lifeCash,{min:0,step:'0.01'})}<div class="note-box full">这里录入的是当前可用现金，持仓市值另行计算。生活保障现金从交易资金中排除。修改币种仅修改计价标签，不执行换汇。</div><div class="full"><button class="btn primary" type="submit">保存资金设置</button></div></form>`)}${card('备份与迁移',`<p>数据由 Hone 服务器按当前登录账号保存，网页内存只保留本次会话数据。保存成功后可从其他设备重新加载。</p><div class="stack">${btn('导出完整 JSON 备份','export','primary')}${btn('导入 JSON 备份','import','secondary')}${btn('导出持仓 CSV','csv','secondary')}${btn('导出成交 CSV','trades-csv','secondary')}${btn('查看服务器恢复点','history','secondary')}</div><p class="small muted">导入会替换当前账户，操作时准备当前数据备份链接，请点击下载并保留。不会读取或迁移此前独立网页版的浏览器存储。</p>${storageError?btn('导出当前服务器账户副本','raw-export','secondary'):''}`)}${card('投资规则',`<div class="metric-row"><span>组合压力预算</span><strong>${s.budget}%</strong></div><div class="metric-row"><span>单票 / 单主题上限</span><strong>${s.singleLimit}% / ${s.themeLimit}%</strong></div><div class="metric-row"><span>月度战术调整提醒阈值</span><strong>${s.maxMonthly} 个百分点</strong></div><p class="small muted">这些是需要你确认的初始测试参数，不是已验证的最优配置。</p>`,btn('修改规则','edit-risk','secondary small'))}${card('使用范围',`<div class="stack"><div>✓ 持仓登记、证据跟踪、情景演算、手工成交记账</div><div>✓ 交易前检查、交易后复盘、备份与导出</div><div class="muted">行情、券商、HOne-Quant 尚未连接。支持手工资金流水与拆股登记；尚不支持融资、做空、期权、自动换汇与自动公司行动。</div></div><p class="small muted">拆股在对应标的中登记，分红通过资金流水登记；持仓转入应先与券商对账，再修正基线并记录事件。</p>`)}</div>`;}
function method(){return heading('BAMANG METHODOLOGY V3.0','把长期投资变成日常流程','以企业研究、证据复核与风险预算连接日常交易管理。')+`<div class="note-box" style="margin-bottom:24px"><strong>以稀缺性与差异化选企业，以长期现金流判断价值，以风险预算控制仓位，以护城河变化决定持有纪律。</strong></div><div class="rules-grid">${[['01','企业研究','将主要研究精力放在企业。稀缺性 → 相对差异化 → 价值捕获 → 优势持续性，形成可验证的因果链。'],['02','证据复核','财报与重大事件触发复核，关注相对毛利、增长、份额、现金流、ROIC 与进入门槛；先核实消息。'],['03','方向估值','按业务选择 PE、EV/Sales 或 DCF。记录悲观／基准／乐观区间与假设，不强制每周精确重估。'],['04','动态杠铃','结合宏观、关键事件与市场水温评估成长、防守和现金。股票防守端仍可能下跌，不视作零风险。'],['05','有因交易','把逻辑变化、估值变化、风险再平衡分别记录。正常波动或已有较大盈利，不自动成为卖出条件。'],['06','独立复盘','长期持有、固定杠铃和动态覆盖应在可比口径下验证。当前工具不声称策略已回测有效。']].map(([n,t,b])=>`<section class="rule-card"><span class="rule-number">${n}</span><h2>${t}</h2><p>${b}</p></section>`).join('')}</div>`+card('日常操作顺序',`<ol class="stack"><li>首次使用：在已登录的 Hone 账户内，填现金、持仓、计价币种和风险约束。</li><li>盘前：更新价格日期，检查新增事件、逻辑变化和集中度。</li><li>考虑交易时：写计划、看交易后压力结果，完成四项人工审查。</li><li>实际交易后：录入真实成交价格、数量和费用，系统更新持仓与现金。</li><li>收盘后：写复盘并导出备份；没有触发条件时允许保持不动。</li></ol><p class="small muted">80/20 是研究精力分配，不是机械评分。月度 5 个百分点、缓冲带 5 个百分点等来自策略模板的初始测试示例，需要自行确认。</p>`);}

function field(name,label,type='text',value='',o={}){if(type==='select'&&value!==''&&!(o.options||[]).some(x=>String(x[0])===String(value)))o={...o,options:[[value,labels[value]||value],...(o.options||[])]};let attrs=`name="${name}" id="f-${name}" ${o.required?'required':''}`;if(o.min!==undefined)attrs+=` min="${o.min}"`;if(o.max!==undefined)attrs+=` max="${o.max}"`;if(type==='number')attrs+=' step="any"';else if(o.step)attrs+=` step="${o.step}"`;const input=type==='textarea'?`<textarea ${attrs} rows="${o.rows||3}" maxlength="12000" placeholder="${esc(o.placeholder||'')}">${esc(value)}</textarea>`:type==='select'?`<select ${attrs}>${(o.options||[]).map(x=>`<option value="${esc(x[0])}" ${String(x[0])===String(value)?'selected':''}>${esc(x[1])}</option>`).join('')}</select>`:`<input ${attrs} type="${type}" value="${esc(value)}" ${type==='text'?'maxlength="250"':''} placeholder="${esc(o.placeholder||'')}">`;return `<div class="field ${o.full?'full':''}"><label for="f-${name}">${label}</label>${input}${o.help?`<small class="muted">${o.help}</small>`:''}</div>`;}
function openModal(title,body,formId,footer='保存',desc=''){const modal=$('#modal');$('#modal-content').innerHTML=`<div class="modal-header"><div><h2>${title}</h2>${desc?`<p class="muted small">${desc}</p>`:''}</div>${btn('✕','close-modal','ghost','aria-label="关闭弹窗"')}</div><form id="${formId}"><div class="modal-body">${body}<div class="form-error negative" id="form-error" role="alert"></div></div><div class="modal-footer">${btn('取消','close-modal','secondary')}<button class="btn primary" type="submit">${footer}</button></div></form>`;modalInitial=JSON.stringify([...new FormData($('#'+formId))]);modal.setAttribute('aria-labelledby','modal-title');$('#modal h2').id='modal-title';modal.showModal();placeDownloadPanel();syncHostStatus();}
function editHolding(id){const h=state.holdings.find(h=>h.id===id)||{id:uid(),symbol:'',name:'',sector:'芯片',theme:'AI',bucket:'core',quantity:0,cost:0,price:0,priceDate:today(),scarcity:'unknown',differentiation:'unknown',valuation:'unknown',thesis:'',invalidation:'',evidence:'',reviewDate:'',nextReview:'',low:0,base:0,high:0};const changes=['stronger','stable','weaker','unknown'].map(k=>[k,labels[k]]);openModal(id?'编辑持仓与投资逻辑':'添加持仓或观察标的',`<input type="hidden" name="id" value="${h.id}"><div class="form-grid">${field('symbol','证券代码','text',h.symbol,{required:true})}${field('name','企业 / 资产名称','text',h.name,{required:true})}${field('sector','产业板块','select',h.sector,{options:['光通信','存储','电力与能源','芯片','网络安全','应用软件','云','火箭与航天','医疗科技','防守股票','债券','其他',h.sector].filter((x,i,a)=>a.indexOf(x)===i).map(x=>[x,x])})}${field('theme','共同风险主题','text',h.theme,{required:true,help:'同一主题的持仓会合并检查集中度'})}${field('bucket','持仓角色','select',h.bucket,{options:['core','flex','defense'].map(k=>[k,labels[k]])})}${field('quantity','当前数量（0 为观察）','number',h.quantity,{min:0,step:'0.000001',required:true})}${field('cost','当前单位成本','number',h.cost,{min:0,step:'0.000001',required:true})}${field('price','手工参考价','number',h.price,{min:0,step:'0.000001',required:true})}${field('priceDate','参考价日期','date',h.priceDate,{required:true})}${field('valuation','方向性估值判断','select',h.valuation,{options:['attractive','fair','expensive','unknown'].map(k=>[k,labels[k]])})}${field('scarcity','行业稀缺性变化','select',h.scarcity,{options:changes})}${field('differentiation','企业相对差异化变化','select',h.differentiation,{options:changes})}${field('thesis','核心逻辑：为什么竞争者拿不走这些利润？','textarea',h.thesis,{full:true,placeholder:'稀缺性、客户选择、价值捕获、优势能持续多久'})}${field('invalidation','证伪条件：什么证据出现时需要改变判断？','textarea',h.invalidation,{full:true,placeholder:'列出 1—3 个具体条件与观察指标'})}${field('evidence','关键证据 / 来源链接','textarea',h.evidence,{full:true,rows:2})}<div class="full small muted">以下区间是你的个人假设，0 表示未设置；顺序为悲观 ≤ 基准 ≤ 乐观。</div>${field('low','悲观价值 / 股','number',h.low,{min:0,step:'0.01'})}${field('base','基准价值 / 股','number',h.base,{min:0,step:'0.01'})}${field('high','乐观价值 / 股','number',h.high,{min:0,step:'0.01'})}${field('reviewDate','最近逻辑复核','date',h.reviewDate)}${field('nextReview','下次关注日期（可不填）','date',h.nextReview)}</div><div class="note-box">持仓编辑用于初次录入或对账，不自动改变现金。日常买卖请通过“交易计划 → 录入实际成交”。防守股票应承担非零压力损失。</div>`,'holding-form','保存标的');}
function editEvent(id){const e=state.events.find(x=>x.id===id)||{id:uid(),date:today(),symbol:'',type:'重大事件',title:'',source:'',verification:'pending',impact:'neutral',note:'',reviewed:false};openModal(id?'编辑事件与证据':'记录新事件',`<input name="id" type="hidden" value="${e.id}"><div class="form-grid">${field('date','事件日期','date',e.date,{required:true})}${field('symbol','关联代码（宏观可留空）','text',e.symbol)}${field('type','事件类型','select',e.type,{options:['财报','竞争变化','技术路线','供需与价格','宏观政策','重大事件','公司行动',e.type].filter((x,i,a)=>a.indexOf(x)===i).map(x=>[x,x])})}${field('verification','事实核实状态','select',e.verification,{options:['pending','verified','refuted'].map(k=>[k,labels[k]])})}${field('title','事件摘要','text',e.title,{full:true,required:true})}${field('source','原始来源或链接','textarea',e.source,{full:true,required:true,rows:2})}${field('followUp','下次跟进日期（可不填）','date',e.followUp||'')}${field('impact','影响方向（个人判断）','select',e.impact,{options:['positive','neutral','negative'].map(k=>[k,labels[k]])})}${field('note','影响链与待验证问题','textarea',e.note,{full:true,required:true,placeholder:'事实是什么 → 影响稀缺或差异化的哪一环 → 是否影响现金流 → 哪些尚待验证'})}</div>`,'event-form','保存事件','修改事件内容后会重新进入待复核状态。');}
function editRisk(){const s=state.settings;openModal('风险预算与配置规则',`<div class="note-box">阈值由你确定，初始参数只是策略模板中的测试示例。成长、防守、现金目标必须合计 100%。</div><div class="form-grid">${[['budget','组合压力损失预算 %'],['singleLimit','单一标的上限 %'],['themeLimit','共同主题上限 %'],['targetGrowth','成长目标 %'],['targetDefense','防守目标 %'],['targetCash','现金目标 %'],['buffer','再平衡缓冲带（百分点）'],['maxMonthly','月度战术调整阈值（百分点）'],['growthShock','成长资产压力跌幅 %'],['defenseShock','防守资产压力跌幅 %'],['cashShock','现金压力损失 %']].map(([k,t])=>field(k,t,'number',s[k],{min:0,max:100,step:'0.1',required:true})).join('')}${field('market','市场水温（人工）','select',s.market,{options:[['positive','偏积极'],['neutral','中性'],['negative','偏谨慎'],['unknown','待判断']]})}${field('marketNote','宏观依据与影响路径','textarea',s.marketNote,{full:true,placeholder:'利率、信用、AI 资本开支、重大事件 → 如何改变企业价值或组合风险？'})}</div>`,'risk-form','保存规则');}
function newPlan(id){const available=state.holdings.filter(h=>!h.archived);if(!available.length){toast('请先添加持仓或观察标的');navigate('holdings');return;}const h=available.find(x=>x.id===id)||available[0];if(id&&state.holdings.find(x=>x.id===id)?.archived){toast('请先恢复这个观察标的，再建立计划。');return;}openModal('新建交易计划',`<div class="progress-steps"><span class="step active">1 写计划</span><span class="step">2 人工审查</span><span class="step">3 录入成交</span></div><div class="form-grid">${field('holdingId','交易标的','select',h.id,{options:available.map(h=>[h.id,`${h.symbol} · ${h.name}`])})}${field('side','方向','select','buy',{options:[['buy','买入'],['sell','卖出']]})}${field('date','计划日期','date',today(),{required:true})}${field('reason','本次操作的主要原因','select','opportunity',{options:['opportunity','thesis','valuation','risk'].map(k=>[k,labels[k]])})}${field('quantity','计划数量','number',1,{min:0.000001,step:'0.000001',required:true})}${field('price','计划成交价','number',h.price,{min:0.000001,step:'0.000001',required:true})}${field('fee','预计费用','number',0,{min:0,step:'0.01',required:true})}${field('rationale','操作依据与预期（必填）','textarea','',{full:true,required:true,placeholder:'发生了什么变化？为什么现在行动？什么情况下取消计划？'})}</div><div id="plan-preview" class="note-box"></div>`,'plan-form','保存为待审查计划','本工具不会向券商发送订单。');updatePlanPreview();}
function draftFromForm(form){const o=Object.fromEntries(new FormData(form));return {...o,quantity:Number(o.quantity),price:Number(o.price),fee:Number(o.fee),symbol:state.holdings.find(h=>h.id===o.holdingId)?.symbol};}
function updatePlanPreview(){const form=$('#plan-form');if(!form)return;const p=draftFromForm(form),sim=simulatePlan(state,p);$('#plan-preview').innerHTML=sim.valid?`<strong>交易后情景预览</strong><div class="metric-row"><span>现金</span><strong>${money(sim.after.cash)}</strong></div><div class="metric-row"><span>成长占比</span><strong>${pct(sim.before.growthPct)} → ${pct(sim.after.growthPct)}</strong></div><div class="metric-row"><span>压力损失</span><strong>${pct(sim.before.stressPct)} → ${pct(sim.after.stressPct)}</strong></div><div class="small muted">持仓继续按已录入参考价估值；成交价用于资金与成本核算。成交价不同于参考价时，资产总额会相应变化。</div>${sim.after.stressPct>state.settings.budget?'<p class="negative">交易后压力损失超预算，请重新审查。</p>':''}`:`<strong class="negative">${esc(sim.errors.join('；'))}</strong>`;}
function reviewPlan(id){const p=state.plans.find(p=>p.id===id);const sim=simulatePlan(state,p);const h=state.holdings.find(h=>h.id===p.holdingId);openModal(`审查 ${esc(p.symbol)} 的${labels[p.side]}计划`,`<input type="hidden" name="id" value="${p.id}"><p>${esc(p.rationale)}</p><div class="note-box">${sim.valid?`交易后现金 ${money(sim.after.cash)} · 压力损失 ${pct(sim.after.stressPct)} / 预算 ${pct(state.settings.budget)}`:esc(sim.errors.join('；'))}</div><div class="small muted" style="margin-top:16px">企业逻辑：${esc(h?.thesis||'尚未填写')}<br>证伪条件：${esc(h?.invalidation||'尚未填写')}</div><div class="checklist">${[['thesis','我已复核稀缺性、差异化与证伪条件'],['value','我已检查估值方向和未来回报假设'],['risk','我已检查现金、集中度与交易后压力风险'],['evidence','关键证据已经核实，操作理由与来源已记录']].map(([k,t])=>`<label class="check-row"><input type="checkbox" name="${k}" required ${p.checklist?.[k]?'checked':''}><span>${t}</span></label>`).join('')}</div><div class="note-box">完成审查不会产生交易。即使超出提醒阈值，是否执行仍由你判断；可使用“修改计划”调整内容，修改后需要重新审查。</div>`,'review-plan-form','确认审查完成');}
function executionModal(id){const p=state.plans.find(p=>p.id===id);openModal(`录入 ${esc(p.symbol)} 的实际成交`,`<input type="hidden" name="id" value="${p.id}"><div class="note-box">仅在券商已经成交后填写。这会更新本工具内的数量、成本和现金；每笔计划只能记账一次。</div><div class="form-grid">${field('quantity','实际成交数量','number',p.quantity,{min:0.000001,step:'0.000001',required:true})}${field('price','实际成交价格','number',p.price,{min:0.000001,step:'0.000001',required:true})}${field('fee','实际手续费','number',p.fee,{min:0,step:'0.01',required:true})}${field('date','实际成交日期','date',today(),{required:true})}</div><label class="check-row"><input type="checkbox" name="confirmed" required><span>我确认这是已经发生的成交，数据与券商记录一致。</span></label>`,'execute-form','确认成交并记账','按实际成交先后顺序记账；同日也须按顺序。部分成交按本次数量登记，剩余数量另建计划。');}
function journalModal(id){const j=state.journal.find(x=>x.id===id)||{id:uid(),date:today(),discipline:'none',lesson:'',next:''};openModal(id?'编辑复盘':'写下今天的复盘',`<input type="hidden" name="id" value="${j.id}"><div class="form-grid">${field('date','复盘日期','date',j.date,{required:true})}${field('discipline','执行自评','select',j.discipline,{options:[['none','持有不动'],['yes','遵守纪律'],['no','存在偏离']]})}${field('lesson','今天的决定、证据与得失','textarea',j.lesson,{full:true,required:true,placeholder:'为什么交易或不交易？判断和执行有什么差别？'})}${field('next','下次行动与待验证的问题','textarea',j.next,{full:true})}</div>`,'journal-form','保存复盘');}
function clearDownload(){clearTimeout(downloadTimer);downloadPanel?.remove();downloadPanel=null;if(downloadUrl)URL.revokeObjectURL(downloadUrl);downloadUrl=null;}
function placeDownloadPanel(){if(downloadPanel)($('#modal').open?$('#modal'):document.body).append(downloadPanel);}
function download(content,name,type='application/json'){
  if(!state)throw Error('账户已清空，无法准备下载。');
  clearDownload();
  if(parent!==window){
    const text=String(content),mime=/\.md$/i.test(name)&&type==='text/plain'?'text/markdown':type;
    if(new TextEncoder().encode(text).byteLength>8*1024*1024)throw Error('导出内容超过 8 MiB，无法在内嵌工具中准备下载。');
    parent.postMessage({type:'hone:trade-export',name,content:text,mime},location.origin);
    toast('请点击工具上方的下载链接保存文件');
    return;
  }
  downloadUrl=URL.createObjectURL(new Blob([content],{type}));
  downloadPanel=document.createElement('section');downloadPanel.id='download-panel';downloadPanel.className='download-panel';downloadPanel.setAttribute('aria-label','文件下载');
  const heading=document.createElement('strong');heading.textContent='文件已准备，请点击下载';
  const fileName=document.createElement('span');fileName.className='download-filename';fileName.textContent=name;
  const hint=document.createElement('p');hint.textContent='下载链接保留 15 分钟；准备新文件、重新加载或退出账户时失效。请确认文件已保存到你的设备。';
  const actions=document.createElement('div');actions.className='actions';
  const link=document.createElement('a');link.className='btn primary';link.href=downloadUrl;link.download=name;link.textContent='点击下载文件';
  const close=document.createElement('button');close.type='button';close.className='btn secondary';close.textContent='关闭下载链接';close.addEventListener('click',clearDownload);
  actions.append(link,close);downloadPanel.append(heading,fileName,hint,actions);placeDownloadPanel();
  downloadTimer=setTimeout(clearDownload,15*60*1000);link.focus();downloadPanel.scrollIntoView({block:'nearest'});
}
async function backup(prefix='巴芒交易台'){await storeApi.validateIdentity();download(JSON.stringify(state,null,2),`${prefix}_${mode}_${today()}.json`);}
function tradesCSV(){const filters=view==='review'?{from:reportFrom,to:reportTo}:{};download(tradeCSV(state,filters),`巴芒成交_${mode}_${today()}.csv`,'text/csv;charset=utf-8');}
function updateScenario(){const form=$('#risk-inline');if(!form)return;const next=clone(state);for(const k of ['growthShock','defenseShock','cashShock']){next.settings[k]=Number(form.elements[k].value);$(`#${k}-label`).textContent=next.settings[k]+'%';}const p=portfolio(next);$('#scenario-result').innerHTML=`<div class="metric-row"><span>情景压力损失</span><strong class="${p.stressPct>state.settings.budget?'negative':''}">${pct(p.stressPct)} · ${money(p.stressLoss)}</strong></div><span class="small">${p.stressPct>state.settings.budget?'超出设定预算，需复核风险敞口。':'未超过设定预算，不代表实际最大回撤受保证。'}</span>`;}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(!state)return;if(uiSaving){toast('正在保存，请等待完成。');return;}try{if(['csv','trades-csv','raw-export'].includes(a))await storeApi.validateIdentity();if(a==='navigate')navigate(b.dataset.view);else if(a==='close-modal')requestClose();else if(a==='new-holding'||a==='edit-holding')editHolding(id);else if(a==='new-event'||a==='edit-event')editEvent(id);else if(a==='review-event'){const next=clone(state),event=next.events.find(x=>x.id===id);event.reviewed=!event.reviewed;await commit(next);render();}else if(a==='new-plan')newPlan(id);else if(a==='edit-risk')editRisk();else if(a==='filter-plan'){planFilter=b.dataset.filter;render();}else if(a==='review-plan')reviewPlan(id);else if(a==='execute-plan')executionModal(id);else if(a==='cancel-plan'){const next=clone(state),p=next.plans.find(x=>x.id===id);if(['draft','reviewed'].includes(p.status))p.status='cancelled';await commit(next);render();toast('已取消计划，持仓与现金未发生变化。');}else if(a==='new-journal'||a==='edit-journal')journalModal(id);else if(a==='export')await backup();else if(a==='csv')download(csvExport(state),`巴芒持仓_${mode}_${today()}.csv`,'text/csv;charset=utf-8');else if(a==='trades-csv')tradesCSV();else if(a==='import')$('#import-file').click();else if(a==='raw-export')download(storeApi.exportRaw()||'{}',`服务器账户备份_${today()}.json`);}catch(err){toast(err.message);}if(state&&view==='risk')updateScenario();});
document.addEventListener('change',async e=>{if(!state||uiSaving)return;if(e.target.dataset.check){try{const next=clone(state),d=today();next.checks[d]??={};next.checks[d][e.target.dataset.check]=e.target.checked;await commit(next);render();}catch(err){e.target.checked=!e.target.checked;toast(err.message);}}if(e.target.closest('#plan-form')){if(e.target.name==='holdingId')$('#f-price').value=state.holdings.find(h=>h.id===e.target.value).price;updatePlanPreview();}});
document.addEventListener('input',e=>{if(!state)return;if(e.target.id==='holding-search'){const start=e.target.selectionStart;search=e.target.value;render();const inp=$('#holding-search');inp.focus();inp.setSelectionRange(start,start);}if(e.target.closest('#plan-form'))updatePlanPreview();if(e.target.closest('#risk-inline'))updateScenario();});
document.addEventListener('submit',async e=>{e.preventDefault();if(!state||uiSaving)return;const form=e.target,raw=Object.fromEntries(new FormData(form)),next=clone(state);try{if(form.getAttribute('id')==='holding-form'){const nums=['quantity','cost','price','low','base','high'];for(const k of nums)raw[k]=Number(raw[k]);raw.symbol=raw.symbol.trim().toUpperCase();raw.name=raw.name.trim();if(!raw.symbol||!raw.name)throw Error('代码与名称不能为空');if(next.holdings.some(h=>h.id!==raw.id&&h.symbol.toUpperCase()===raw.symbol))throw Error('此代码已存在，请编辑现有标的');if(raw.quantity>0&&raw.price<=0)throw Error('持有资产需要大于 0 的参考价');if(raw.low||raw.base||raw.high){if(!(raw.low>0&&raw.low<=raw.base&&raw.base<=raw.high))throw Error('估值区间需要满足：0 < 悲观 ≤ 基准 ≤ 乐观');}const idx=next.holdings.findIndex(x=>x.id===raw.id);if(idx<0)next.holdings.push(raw);else next.holdings[idx]={...next.holdings[idx],...raw};await commit(next,'更新持仓逻辑');}else if(form.getAttribute('id')==='event-form'){raw.symbol=raw.symbol.trim().toUpperCase();raw.reviewed=false;const idx=next.events.findIndex(x=>x.id===raw.id);raw.updatedAt=new Date().toISOString();if(raw.followUp&&(!/^\d{4}-\d{2}-\d{2}$/.test(raw.followUp)||Number.isNaN(Date.parse(raw.followUp))))throw Error('跟进日期无效');if(idx<0)next.events.push(raw);else next.events[idx]=raw;await commit(next,'更新事件证据');}else if(form.getAttribute('id')==='risk-form'){for(const k of Object.keys(raw))if(!['market','marketNote'].includes(k))raw[k]=Number(raw[k]);if(Math.abs(raw.targetGrowth+raw.targetDefense+raw.targetCash-100)>0.001)throw Error('成长、防守与现金目标合计必须为 100%');Object.assign(next.settings,raw);await commit(next);}else if(form.getAttribute('id')==='risk-inline'){for(const k of Object.keys(raw))next.settings[k]=Number(raw[k]);await commit(next);render();updateScenario();toast('情景已保存');return;}else if(form.getAttribute('id')==='account-form'){if(raw.currency!==state.settings.currency&&(state.holdings.length>0||state.plans.length>0||state.settings.cash>0||state.settings.lifeCash>0||(state.cashFlows||[]).length>0||(state.corporateActions||[]).length>0))throw Error('已有资金、标的或交易记录时不能直接切换币种；请先将全部金额及历史记录按统一口径折算后通过备份导入。');Object.assign(next.settings,{currency:raw.currency,cash:Number(raw.cash),lifeCash:Number(raw.lifeCash)});await commit(next);render();toast('资金设置已保存');return;}else if(form.getAttribute('id')==='plan-form'){const p={...draftFromForm(form),id:form.dataset.editId||uid(),status:'draft',checklist:{thesis:false,value:false,risk:false,evidence:false}};const sim=simulatePlan(state,p);if(!sim.valid)throw Error(sim.errors.join('；'));if(form.dataset.editId)await commit(updatePlan(state,form.dataset.editId,draftFromForm(form)),'修改交易计划');else{next.plans.push(p);await commit(next,'建立交易计划');}}else if(form.getAttribute('id')==='review-plan-form'){const p=next.plans.find(p=>p.id===raw.id);if(!['draft','reviewed'].includes(p.status))throw Error('计划状态已变化');for(const k of ['thesis','value','risk','evidence'])if(!raw[k])throw Error('请完成全部四项审查');const sim=simulatePlan(state,p);if(!sim.valid)throw Error(sim.errors.join('；'));await commit(reviewPlanState(state,raw.id,{thesis:true,value:true,risk:true,evidence:true}),'审查交易计划');}else if(form.getAttribute('id')==='execute-form'){if(!raw.confirmed)throw Error('请确认实际成交');await commit(executePlan(state,raw.id,{price:Number(raw.price),quantity:Number(raw.quantity),fee:Number(raw.fee),date:raw.date}),'登记实际成交');}else if(form.getAttribute('id')==='journal-form'){const idx=next.journal.findIndex(x=>x.id===raw.id);if(idx<0)next.journal.push(raw);else next.journal[idx]=raw;await commit(next);}else return;$('#modal').close();render();if(view==='risk')updateScenario();toast('已保存');}catch(err){showFormError(err);}});
$('#import-file').addEventListener('change',async e=>{if(!state||uiSaving){e.target.value='';return;}const generation=lifecycle,file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>2*1024*1024)throw Error('备份文件超过 2 MiB，请减少内容后再导入；保存信息也计入服务器限制');const text=await file.text();if(generation!==lifecycle||!state)return;const data=JSON.parse(text),v=validateState(data);if(!v.valid)throw Error(v.errors.slice(0,5).join('；'));openModal('导入备份并替换当前账户',`<p>将导入 <strong>${data.holdings.length} 个标的、${data.events.length} 条事件、${data.plans.length} 笔计划</strong>，覆盖当前 Hone 账户。</p><div class="note-box">确认后将准备当前数据备份链接，再导入新数据。请点击下载文件并保留备份，便于恢复。</div><label class="check-row"><input type="checkbox" required><span>确认导入此文件，并替换当前账户的数据。</span></label>`,'import-confirm','备份并导入');$('#import-confirm').addEventListener('submit',async ev=>{ev.preventDefault();try{if(generation!==lifecycle||!state||uiSaving)throw Error('账户未就绪或正在保存。');await persistOperation(async()=>{await backup('导入前备份');return storeApi.replace(clone(data),'导入备份');});storageError='';$('#modal').close();render();toast('服务器已保存导入数据；原数据备份已准备，请点击下载文件并保留');}catch(err){showFormError(err);}});}catch(err){toast('导入失败：'+err.message);}});
window.addEventListener('hashchange',()=>{view=location.hash.slice(1)||'dashboard';render();if(state&&view==='risk')updateScenario();});

function onboarding(){if(state.holdings.length||state.settings.cash>0)return '';return `<section class="onboarding"><div><span class="eyebrow">第一次使用 · 3 步建立账户</span><h2>先建立自己的投资基线</h2><p>账户还没有数据。先选择币种和资金，再录入持仓，最后确认个人风险预算。</p></div><div class="actions">${btn('1 设置资金','navigate','primary','data-view="settings"')}${btn('2 添加持仓','new-holding','secondary')}${btn('3 确认风险预算','edit-risk','secondary')}</div></section>`;}
function requestClose(){if(uiSaving){toast('正在保存，请等待完成。');return;}const f=$('#modal form');const changed=f&&JSON.stringify([...new FormData(f)])!==modalInitial;if(!changed){$('#modal').close();return;}if(!$('#discard-confirm')){const notice=document.createElement('div');notice.id='discard-confirm';notice.className='discard-confirm';notice.setAttribute('role','alert');notice.innerHTML='<strong>还有未保存的修改</strong><p>继续编辑可保留输入，放弃则关闭且不保存。</p><div class="actions">'+btn('继续编辑','continue-edit','primary small')+btn('放弃未保存修改','discard-changes','secondary small')+'</div>';$('.modal-footer').before(notice);}$('#discard-confirm').scrollIntoView({block:'nearest'});$('#discard-confirm [data-action="continue-edit"]').focus();}
function cashFlowModal(){openModal('登记资金流水',`<div class="note-box">登记已发生的资金变化，避免直接改现金后丢失原因。入金与出金不计入交易盈亏，分红单独统计。</div><div class="form-grid">${field('type','流水类型','select','deposit',{options:[['deposit','入金'],['withdrawal','出金'],['dividend','现金分红（到账净额）'],['fee','账户费用']]})}${field('amount','实际金额','number','',{required:true,min:0.01,step:'0.01'})}${field('date','发生日期','date',today(),{required:true})}${field('holdingId','关联标的（可不填）','select','',{options:[['','不关联标的'],...state.holdings.map(h=>[h.id,h.symbol])]})}${field('note','流水说明 / 对账依据','textarea','',{required:true,full:true,placeholder:'例如：券商转入到账、现金分红净额、托管费；记录来源与口径'})}</div><div class="small muted">当前可用现金 ${money(state.settings.cash)}。按实际发生顺序录入。</div>`,'cash-flow-form','登记并更新现金');}
function splitModal(id){const h=state.holdings.find(h=>h.id===id);if(!h||h.quantity<=0){toast('拆股登记仅适用于当前持有的标的');return;}openModal(`登记 ${esc(h.symbol)} 拆股 / 合股`, `<input name="holdingId" type="hidden" value="${h.id}"><div class="note-box">请在实际生效并与券商对账后登记。数量乘以比例，单位成本、参考价和个人价值区间除以比例，市值与总成本保持不变。相关未成交计划会被取消，需重新建立。</div><div class="form-grid">${field('date','实际生效日期','date',today(),{required:true})}${field('ratio','新股数 ÷ 原股数','number','',{required:true,min:0.000001,step:'0.000001',help:'1 拆 8 填 8；10 合 1 填 0.1'})}${field('note','公告来源与对账说明','textarea','',{required:true,full:true})}</div><label class="check-row"><input type="checkbox" name="confirmed" required><span>已核对实际生效比例，确认没有重复登记。</span></label>`,'split-form','确认公司行动');}
function bulkQuotes(){quotePreview=null;openModal('批量更新手工报价',`<div class="note-box">从模板或表格粘贴 CSV。只更新已存在标的的价格和日期，不改变数量或成本。没有连接实时行情。</div><div class="actions" style="margin:12px 0">${btn('下载当前报价模板','quote-template','secondary small')}</div>${field('quotes','CSV 报价文本','textarea','',{full:true,required:true,rows:7,placeholder:'symbol,price,date\nNVDA,140,2026-11-16'})}<div class="actions" style="margin:12px 0">${btn('校验并预览','preview-quotes','secondary')}</div><div id="quote-preview" aria-live="polite"></div><label class="check-row"><input name="confirmed" type="checkbox" required><span>已核对来源、日期和计价币种，确认更新预览中的报价。</span></label>`,'quote-form','应用已校验报价');}
function previewQuotes(){const text=$('#f-quotes').value;quotePreview={text,...parseQuoteCSV(text,state.holdings)};$('#quote-preview').innerHTML=quotePreview.errors.length?`<div class="error-text">${quotePreview.errors.map(esc).join('<br>')}</div>`:`<div class="table-wrap"><table class="data-table"><thead><tr><th>标的</th><th>原价格</th><th>新价格</th><th>日期</th></tr></thead><tbody>${quotePreview.rows.map(r=>`<tr><td>${esc(r.symbol)}</td><td>${fmt(r.oldPrice,2)}</td><td>${fmt(r.price,2)}</td><td>${esc(r.date)}</td></tr>`).join('')}</tbody></table></div><p class="small muted">${quotePreview.rows.length} 条报价校验通过；请确认后应用。</p>`;}
async function historyModal(){const generation=lifecycle,entries=await storeApi.history();if(generation!==lifecycle||!state)return;openModal('服务器恢复点',`<div class="note-box">服务器保留此前最近 8 个已保存版本，按当前 Hone 身份隔离。恢复会替换整个账户，请先查看版本和日期。</div>${entries.length?`<div class="history-list">${entries.map(x=>`<div class="history-row"><div><strong>${esc(x.label)}</strong><div class="small muted">${esc(new Date(x.date).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}))} · 版本 ${x.revision}</div></div><div class="actions">${btn('下载','download-snapshot','secondary small',`data-id="${esc(x.id)}"`)}${btn('恢复此版本','restore-snapshot','ghost small',`data-id="${esc(x.id)}"`)}</div></div>`).join('')}</div>`:empty('还没有恢复点','保存第二个版本后，可以恢复此前已保存版本。')}`,'history-info','关闭');}
async function restoreModal(id){const generation=lifecycle,x=await storeApi.getSnapshot(id);if(generation!==lifecycle||!state)return;openModal('确认恢复服务器账户',`<input type="hidden" name="snapshotId" value="${esc(x.id)}"><p>恢复到 <strong>${esc(x.label)}</strong>（版本 ${x.revision}），包含 ${x.state.holdings.length} 个标的与 ${x.state.plans.length} 笔计划。</p><div class="note-box">确认后先准备当前账户备份链接，再由服务器按版本校验执行恢复。请点击下载文件并保留备份。此期间若其他页面已修改账户，恢复会被拒绝。</div><label class="check-row"><input type="checkbox" name="confirmed" required><span>确认以此恢复点替换当前 Hone 个人交易账户。</span></label>`,'restore-form','备份当前账户并恢复');}

function editPlanModal(id){const p=state.plans.find(p=>p.id===id);if(!p||!['draft','reviewed'].includes(p.status))throw Error('只能修改未记账的计划');newPlan(p.holdingId);const f=$('#plan-form');f.dataset.editId=id;for(const k of ['holdingId','side','date','reason','quantity','price','fee','rationale'])f.elements[k].value=p[k];$('#modal h2').textContent=`修改 ${p.symbol} 的交易计划`;$('#modal .modal-header p').textContent='修改后回到待审查状态，原审查不会沿用。';$('#modal button[type="submit"]').textContent='保存修改并重新审查';modalInitial=JSON.stringify([...new FormData(f)]);updatePlanPreview();}
function riskComparison(){const s=state.settings,p=portfolio(state);const scenarios=[['温和压力',25,5,0],['当前假设',s.growthShock,s.defenseShock,s.cashShock],['更严压力',65,30,2]];return card('多情景对照',`<p class="small muted">两组预设仅用于压力演算，不代表市场预测。点击后先调整滑块，保存才会更新当前假设。</p><div class="table-wrap"><table class="data-table"><thead><tr><th>情景</th><th>成长 / 防守 / 现金跌幅</th><th>现配置损失</th><th>按目标比例的损失</th><th></th></tr></thead><tbody>${scenarios.map(([n,g,d,c],i)=>{const loss=p.total?(p.growth*g+p.defense*d+p.cash*c)/p.total:0,target=(s.targetGrowth*g+s.targetDefense*d+s.targetCash*c)/100;return `<tr><td>${n}</td><td>${g}% / ${d}% / ${c}%</td><td class="${loss>s.budget?'negative':''}">${p.total?pct(loss):'待录入资产'}</td><td>${pct(target)}</td><td>${i!==1?btn('试算','scenario-preset','ghost small',`data-growth="${g}" data-defense="${d}" data-cash="${c}"`):tag('当前')}</td></tr>`;}).join('')}</tbody></table></div>`)+card('共同主题敞口',p.themeWeights.length?`<div class="stack">${p.themeWeights.map(t=>`<div><div class="metric-row"><span>${esc(t.theme)}</span><strong>${pct(t.weight)}</strong></div><div class="exposure-track"><span style="width:${Math.min(100,t.weight)}%"></span></div></div>`).join('')}</div><p class="small muted" style="margin-top:14px">按你填写的共同风险主题聚合，不能替代历史相关性分析。</p>`:empty('暂无资产','录入持仓后显示共同主题敞口。'));}
function ledgerTable(){const flows=(state.cashFlows||[]).slice().reverse(),actions=(state.corporateActions||[]).slice().reverse();return card('全部资金流水与公司行动',!flows.length&&!actions.length?empty('尚未登记资金或公司行动','以后通过资金流水登记入金、出金、分红和费用；拆股在对应标的中登记。'):`<div class="table-wrap"><table class="data-table"><thead><tr><th>日期</th><th>类型 / 标的</th><th>变化</th><th>说明</th></tr></thead><tbody>${flows.map(f=>`<tr><td>${esc(f.date)}</td><td>${({deposit:'入金',withdrawal:'出金',dividend:'分红',fee:'账户费用'})[f.type]}</td><td>${['withdrawal','fee'].includes(f.type)?'−':'+'}${money(f.amount)}</td><td>${esc(f.note)}</td></tr>`).join('')}${actions.map(a=>`<tr><td>${esc(a.date)}</td><td>拆股 / ${esc(state.holdings.find(h=>h.id===a.holdingId)?.symbol||'')}</td><td>数量 × ${fmt(a.ratio,6)}</td><td>${esc(a.note)}</td></tr>`).join('')}</tbody></table></div>`,btn('登记资金流水','cash-flow','secondary small'));}
function metricsPanel(){const m=decisionMetrics(state,{from:reportFrom,to:reportTo});return `<section class="card"><div class="card-header"><h2>期间成交复盘</h2>${btn('打印当前页','print','secondary small')}</div><div class="card-body"><form id="report-filter" class="toolbar"><label>开始 <input name="from" aria-label="复盘开始日期" type="date" value="${esc(reportFrom)}"></label><label>结束 <input name="to" aria-label="复盘结束日期" type="date" value="${esc(reportTo)}"></label><button type="submit" class="btn secondary small">应用日期</button>${btn('全部日期','clear-report-filter','ghost small')}</form><div class="summary-grid"><div><span>已实现交易盈亏</span><strong>${money(m.realizedPnl)}</strong></div><div><span>成交手续费</span><strong>${money(m.fees)}</strong></div><div><span>相对计划价格差额</span><strong>${money(m.slippageCost)}</strong></div><div><span>净入金 / 分红</span><strong>${money(m.externalFlows)} / ${money(m.dividends)}</strong></div></div><p class="small muted">价格差额为正表示实际成交比计划价格更不利，按实际数量计算；这是计划价格对照，不等于严格市场滑点。入出金与分红单列，不与交易盈亏混算。</p><div class="actions">${Object.entries(m.reasonCounts).map(([k,v])=>tag(`${labels[k]||k} ${v} 笔`)).join('')}</div></div></section>`;}
function commandPalette(){openModal('快速前往',`<div class="command-list">${navs.map(([v,i,n])=>btn(`${i} ${n}`,'command-nav','secondary',`data-view="${v}"`)).join('')}${btn('＋ 新建计划','command-plan','primary')}${btn('⇩ 导出今日报告','daily-report','secondary')}</div>`,'command-info','关闭');}

$('#modal').addEventListener('cancel',e=>{e.preventDefault();requestClose();});
window.addEventListener('beforeunload',e=>{if(uiSaving||hasUnsavedChanges()){e.preventDefault();e.returnValue='';}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!state||uiSaving||$('#modal').open)return;commandPalette();}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(!state)return;if(uiSaving){toast('正在保存，请等待完成。');return;}try{if(['quote-template','daily-report','print','download-snapshot'].includes(a))await storeApi.validateIdentity();if(a==='continue-edit'){if($('#discard-confirm'))$('#discard-confirm').remove();else $('#modal').close();}else if(a==='discard-changes')$('#modal').close();else if(a==='cash-flow')cashFlowModal();else if(a==='split')splitModal(id);else if(a==='bulk-quotes')bulkQuotes();else if(a==='quote-template')download(quoteTemplate(state.holdings.filter(h=>!h.archived)),`报价模板_${today()}.csv`,'text/csv;charset=utf-8');else if(a==='preview-quotes')previewQuotes();else if(a==='history')await historyModal();else if(a==='download-snapshot'){const generation=lifecycle,x=await storeApi.getSnapshot(id);if(generation!==lifecycle||!state)return;download(JSON.stringify(x.state,null,2),`恢复点_${mode}_${x.date.slice(0,10)}.json`);}else if(a==='restore-snapshot')await restoreModal(id);else if(a==='edit-plan')editPlanModal(id);else if(a==='remaining-plan'){await commit(makeRemainingPlan(state,id,uid()),'建立剩余数量计划');render();toast('剩余数量已建立新计划，需要重新审查。');}else if(a==='holding-events'){eventSearch=state.holdings.find(h=>h.id===id).symbol;eventFilter='all';navigate('research');}else if(a==='archive-holding'){const next=clone(state),h=next.holdings.find(h=>h.id===id);if(h.quantity>0||next.plans.some(p=>p.holdingId===id&&['draft','reviewed'].includes(p.status)))throw Error('有持仓或未完成计划时不能归档');h.archived=!h.archived;await commit(next,h.archived?'归档观察标的':'恢复观察标的');render();}else if(a==='daily-report'){download(dailyReport(state,today()),`巴芒决策日报_${mode}_${today()}.md`,'text/markdown;charset=utf-8');toast('决策日报已准备，请点击下载文件（基于手工数据）');}else if(a==='scenario-preset'){const f=$('#risk-inline');f.elements.growthShock.value=b.dataset.growth;f.elements.defenseShock.value=b.dataset.defense;f.elements.cashShock.value=b.dataset.cash;updateScenario();f.scrollIntoView({behavior:'smooth',block:'center'});toast('滑块已更新，保存此情景后生效。');}else if(a==='clear-report-filter'){reportFrom='';reportTo='';render();}else if(a==='print')window.print();else if(a==='command-palette')commandPalette();else if(a==='command-nav'){$('#modal').close();navigate(b.dataset.view);}else if(a==='command-plan'){$('#modal').close();newPlan();}}catch(err){toast(err.message);}});
document.addEventListener('change',async e=>{if(!state)return;if(e.target.id==='holding-filter'){holdingFilter=e.target.value;render();}else if(e.target.id==='holding-sort'){holdingSort=e.target.value;render();}else if(e.target.id==='event-filter'){eventFilter=e.target.value;render();}});
document.addEventListener('input',e=>{if(!state)return;if(e.target.id==='event-search'){const pos=e.target.selectionStart;eventSearch=e.target.value;render();$('#event-search').focus();$('#event-search').setSelectionRange(pos,pos);}if(e.target.id==='f-quotes'){quotePreview=null;$('#quote-preview').textContent='内容已变化，请重新校验并预览。';}});
document.addEventListener('submit',async e=>{if(!state||uiSaving){e.preventDefault();return;}const form=e.target,id=form.getAttribute('id'),raw=Object.fromEntries(new FormData(form));if(!['cash-flow-form','split-form','quote-form','history-info','command-info','restore-form','report-filter'].includes(id))return;e.preventDefault();try{if(id==='cash-flow-form'){const flow={...raw,id:uid(),amount:Number(raw.amount)};if(!flow.holdingId)delete flow.holdingId;await commit(recordCashFlow(state,flow),'登记资金流水');}else if(id==='split-form'){if(!raw.confirmed)throw Error('请核对公司行动比例');await commit(applySplit(state,{id:uid(),date:raw.date,holdingId:raw.holdingId,ratio:Number(raw.ratio),note:raw.note}),'登记拆股合股');}else if(id==='quote-form'){if(!quotePreview||quotePreview.text!==raw.quotes||quotePreview.errors.length)throw Error('请先完成校验并核对预览');if(!raw.confirmed)throw Error('请确认报价来源与币种');await commit(applyQuoteRows(state,quotePreview.rows),'批量更新报价');quotePreview=null;}else if(id==='restore-form'){if(!raw.confirmed)throw Error('请确认恢复');await persistOperation(async()=>{await backup('恢复前账户备份');return storeApi.recover(raw.snapshotId);});storageError='';}else if(id==='report-filter'){if(raw.from&&raw.to&&raw.from>raw.to)throw Error('开始日期不能晚于结束日期');decisionMetrics(state,{from:raw.from,to:raw.to});reportFrom=raw.from;reportTo=raw.to;render();return;}else{$('#modal').close();return;}$('#modal').close();render();if(view==='risk')updateScenario();toast('服务器已保存；此前版本可从恢复点查看');}catch(err){showFormError(err);}});

// The host sends only an invalidation event; it never sends a user ID or financial state.
function formSignature(form){return JSON.stringify([...form.elements].filter(el=>el.name&&!['submit','button'].includes(el.type)).map(el=>[el.name,['checkbox','radio'].includes(el.type)?el.checked:el.value]));}
function captureMainForms(){mainInitial=new Map([...document.querySelectorAll('#account-form,#risk-inline')].map(form=>[form.id,formSignature(form)]));}
function hasUnsavedChanges(){if(!state)return false;if(storeApi?.getPendingState())return true;const form=$('#modal form');if($('#modal').open&&form&&JSON.stringify([...new FormData(form)])!==modalInitial)return true;for(const [id,initial] of mainInitial){const current=$('#'+id);if(current&&formSignature(current)!==initial)return true;}return false;}
function syncHostStatus(){if(parent!==window)parent.postMessage({type:'hone:trade-status',dirty:hasUnsavedChanges(),busy:uiSaving},location.origin);}
function showReloadConfirmation(downloaded){const body=`<strong>重新加载会清除本页未提交内容</strong><p>${downloaded?'已准备待保存副本，请点击下载文件并保留后，再确认重新加载。':'尚未提交的表单内容不会自动保存。'}继续后读取服务器当前版本。</p><div class="actions">${btn('继续编辑','continue-edit','primary small')}${btn('确认重新加载','confirm-reload','secondary small')}</div>`;if($('#modal').open){$('#discard-confirm')?.remove();const notice=document.createElement('div');notice.id='discard-confirm';notice.className='discard-confirm';notice.setAttribute('role','alert');notice.innerHTML=body;$('.modal-footer').before(notice);notice.scrollIntoView({block:'nearest'});}else openModal('确认重新加载',body,'history-info','取消');}
function showFormError(error){if(!state)return;const el=$('#form-error');if(!el){toast(error.message);if(storeApi.getPendingState())render();return;}el.textContent=error.message;if(storeApi.getPendingState()){const button=document.createElement('button');button.type='button';button.className='btn secondary small';button.dataset.action='download-pending';button.textContent='下载本次待保存副本';el.append(document.createElement('br'),button);const reload=document.createElement('button');reload.type='button';reload.className='btn secondary small';reload.dataset.action='retry-load';reload.textContent='备份后重新加载';el.append(reload);}syncHostStatus();}
for(const event of ['input','change','click','submit'])document.addEventListener(event,()=>queueMicrotask(syncHostStatus));
$('#modal').addEventListener('close',()=>{quotePreview=null;placeDownloadPanel();syncHostStatus();});
storeApi=createRemoteStore({validate:validateState,createEmpty:createState,onInvalidate:clearSensitive});
let authChannel;
try{authChannel=new BroadcastChannel('hone-auth-lifecycle');authChannel.onmessage=e=>{if(e.data?.type==='invalidate'){loading=false;storeApi.invalidate('Hone 登录状态已变化，本页数据已清空。请重新打开工具。');}};}catch{}
window.addEventListener('hone:auth-invalidated',()=>{loading=false;storeApi.invalidate('Hone 登录状态已变化，本页数据已清空。');});
window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===parent&&e.data?.type==='hone:auth-invalidated'){loading=false;storeApi.invalidate('Hone 登录状态已变化，本页数据已清空。');}});
window.addEventListener('pagehide',()=>{loading=false;storeApi.invalidate('页面已离开，请重新验证登录。');});
window.addEventListener('pageshow',e=>{if(e.persisted)void bootstrap();});
window.addEventListener('focus',()=>void refreshSession());
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')void refreshSession();});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(!['retry-load','download-pending','host-close','confirm-reload'].includes(action))return;try{if(action==='host-close'){if(parent!==window)parent.postMessage({type:'hone:trade-close-request'},location.origin);else location.assign('/chat');}else if(action==='confirm-reload'){if(uiSaving)throw Error('正在保存，请等待完成。');await bootstrap();}else if(action==='download-pending'){await storeApi.validateIdentity();const candidate=storeApi.getPendingState();if(!candidate)throw Error('没有可下载的待保存副本，或登录上下文已清空。');download(JSON.stringify(candidate,null,2),`Hone_待保存交易数据_${today()}.json`);}else{if(uiSaving)throw Error('正在保存，请等待完成后重新加载。');if(storeApi.getPendingState()){await storeApi.validateIdentity();download(JSON.stringify(storeApi.getPendingState(),null,2),`Hone_重新加载前待保存数据_${today()}.json`);showReloadConfirmation(true);return;}if(hasUnsavedChanges()){showReloadConfirmation(false);return;}await bootstrap();}}catch(error){toast(error.message);}});
void bootstrap();
